const memoria = $getWorkflowStaticData('global');
const vistos = memoria.vistos || [];

const eventosRaw = $('Get many events').all().filter(e => e.json.summary || e.json.start);
const correosRaw = $('Get many messages').all().filter(m => m.json.Subject);

const hora = $now.hour;
const momento = hora < 12 ? 'mañana' : hora < 20 ? 'tarde' : 'noche';
const temas = ['disciplina','paciencia','constancia','aprender algo nuevo','familia',
  'descansar sin culpa','valentía','una sola cosa a la vez','pequeñas victorias','empezar aunque cueste'];
const refs = ['Dragon Ball','One Piece','Naruto','Zelda','Dark Souls','Pokémon',
  'League of Legends','Mario','Final Fantasy','Attack on Titan'];
const azar = a => a[Math.floor(Math.random() * a.length)];

const eventos = eventosRaw.map(e => ({
  titulo: e.json.summary || 'Sin título',
  inicio: e.json.start?.dateTime || e.json.start?.date
}));
const correos = correosRaw.map(m => ({
  id: m.json.id, de: m.json.From, asunto: m.json.Subject, extracto: m.json.snippet?.substring(0, 150)
}));
const nuevos = correos.filter(c => !vistos.includes(c.id));

const ultimo = memoria.ultimo || 'ninguno';
memoria.vistos = [...new Set([...correos.map(c => c.id), ...vistos])].slice(0, 300);
memoria.ultimo = $now.toFormat('dd/MM HH:mm');

return [{ json: {
  fecha: $now.toFormat('dd/MM/yyyy'), hora: $now.toFormat('HH:mm'), momento,
  tema: azar(temas), referencia: azar(refs),
  ultimo_reporte: ultimo,
  num_nuevos: nuevos.length,
  num_ya_avisados: correos.length - nuevos.length,
  eventos: eventos.length ? JSON.stringify(eventos) : 'No hay eventos',
  correos_nuevos: nuevos.length ? JSON.stringify(nuevos.map(({id, ...r}) => r)) : 'Ninguno'
}}];

const raw = $input.first().json.content.parts[0].text;
const d = JSON.parse(raw.replace(/```json|```/g, '').trim());

const texto = d.texto
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<(?!\/?(b|i|u|s|code|pre|a)\b)[^>]*>/gi, '');

return [{ json: { texto, guion: d.guion } }];
